mapper.select:

SELECT a.recipient_name, a.phone, a.country_code, a.state_province, a.city,
       a.district, a.address_line1, a.address_line2, a.postal_code, a.label
FROM shipping_addresses a
JOIN carts c ON c.selected_address_id = a.id
WHERE c.user_id = #{customerId}
  AND a.user_id = #{customerId}

mapper.insert:
INSERT INTO cart_items (cart_id, product_id, merchant_id, product_name, thumbnail_url, unit_price, quantity, created_at, updated_at)
SELECT c.id, #{item.productId}, #{item.merchantId}, #{item.productName}, #{item.thumbnailUrl}, #{item.unitPrice}, #{item.quantity}, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM carts c WHERE c.user_id = #{customerId}
ON CONFLICT DO NOTHING
